package github.com.gengyoubo.mfcl.idea;

import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.zip.ZipFile;

/** Locates classes in the name-only JARs generated by mfcl.direct, without relying on IDEA indexing. */
final class LegacyProjectJars {
    record Candidate(String qualifiedName, Path jar) {}
    private record Cached(long size, long modified, Map<String, List<String>> names) {}
    private static final Map<Path, Cached> CACHE = new ConcurrentHashMap<>();

    static List<Path> runtimeJars(Path project) {
        if (project == null) return List.of();
        var result = new LinkedHashSet<Path>();
        Path sets = project.resolve("build/mfcl-direct");
        if (Files.isDirectory(sets)) {
            try (var dirs = Files.list(sets)) {
                for (Path dir : dirs.filter(Files::isDirectory).sorted().toList())
                    addIfFile(result, dir.resolve("minecraft-forge-1.7.10-mcp.jar"));
            } catch (IOException ignored) { }
        }
        addIfFile(result, project.resolve("run/mfcl/runtime/1.7.10/minecraft-forge-1.7.10-srg.jar"));
        for (String file : List.of("gradle.properties", "gradle-local.properties")) {
            Path propertiesPath = project.resolve(file);
            if (!Files.isRegularFile(propertiesPath)) continue;
            Properties properties = new Properties();
            try (var input = Files.newBufferedReader(propertiesPath)) {
                properties.load(input);
                String runtime = properties.getProperty("legacyRuntimeDir");
                if (runtime != null && !runtime.isBlank())
                    addIfFile(result, project.resolve(runtime).resolve("minecraft-forge-1.7.10-srg.jar"));
                String run = properties.getProperty("mfclRunDir");
                if (run != null && !run.isBlank())
                    addIfFile(result, project.resolve(run).resolve("mfcl/runtime/1.7.10/minecraft-forge-1.7.10-srg.jar"));
            } catch (IOException | RuntimeException ignored) { }
        }
        return List.copyOf(result);
    }

    private static void addIfFile(Set<Path> paths, Path path) {
        if (Files.isRegularFile(path)) paths.add(path.toAbsolutePath().normalize());
    }

    static List<Candidate> find(Path project, String simpleName) {
        if (project == null || simpleName == null || simpleName.isBlank()) return List.of();
        Path sets = project.resolve("build/mfcl-direct");
        if (!Files.isDirectory(sets)) return List.of();
        Map<String, Candidate> candidates = new TreeMap<>();
        try (var directories = Files.list(sets)) {
            for (Path dir : directories.filter(Files::isDirectory).sorted().toList()) {
                Path jar = dir.resolve("legacy-names-1.7.10.jar");
                if (!Files.isRegularFile(jar)) continue;
                for (String qualified : index(jar).getOrDefault(simpleName, List.of()))
                    candidates.putIfAbsent(qualified, new Candidate(qualified, jar));
            }
        } catch (IOException | RuntimeException ignored) { /* The build may be replacing a JAR. */ }
        return List.copyOf(candidates.values());
    }

    private static Map<String, List<String>> index(Path jar) throws IOException {
        long size = Files.size(jar), modified = Files.getLastModifiedTime(jar).toMillis();
        Cached existing = CACHE.get(jar);
        if (existing != null && existing.size() == size && existing.modified() == modified) return existing.names();
        Map<String, List<String>> names = new HashMap<>();
        try (ZipFile zip = new ZipFile(jar.toFile())) {
            var entries = zip.entries();
            while (entries.hasMoreElements()) {
                String entry = entries.nextElement().getName();
                if (!entry.endsWith(".class") || entry.startsWith("META-INF/") || entry.endsWith("package-info.class") || entry.equals("module-info.class")) continue;
                String binary = entry.substring(0, entry.length() - 6);
                String simple = binary.substring(Math.max(binary.lastIndexOf('/'), binary.lastIndexOf('$')) + 1);
                if (simple.isEmpty() || Character.isDigit(simple.charAt(0))) continue;
                names.computeIfAbsent(simple, ignored -> new ArrayList<>()).add(binary.replace('/', '.').replace('$', '.'));
            }
        }
        CACHE.put(jar, new Cached(size, modified, names));
        return names;
    }
}
